// Regenerate the plugin-only schema from the installed Better Auth definitions.
import { writeFileSync } from "node:fs"
import { mcp } from "../packages/auth/node_modules/@better-auth/mcp/dist/index.mjs"
import { jwt } from "../packages/auth/node_modules/better-auth/dist/plugins/jwt/index.mjs"
const tables = {
  ...jwt().schema,
  ...mcp({
    resource: "http://localhost:3000/mcp",
    loginPage: "/sign-in",
    consentPage: "/connect",
  }).schema,
}
const snake = (value) =>
  value.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`)
let source =
  '// Generated by scripts/generate-auth-schema.mjs. Regenerate when auth plugins change.\nimport { sqliteTable, text, integer, index, uniqueIndex } from "drizzle-orm/sqlite-core"\nimport { user, session } from "@workspace/auth/schema"\n\n'
for (const [name, table] of Object.entries(tables)) {
  const fields = ['id: text("id").primaryKey()']
  const indexes = []
  for (const [key, field] of Object.entries(table.fields)) {
    let column
    if (field.type === "date")
      column = `integer("${snake(key)}", {mode:"timestamp_ms"})`
    else if (field.type === "boolean")
      column = `integer("${snake(key)}", {mode:"boolean"})`
    else if (field.type === "number") column = `integer("${snake(key)}")`
    else if (field.type === "string[]")
      column = `text("${snake(key)}", {mode:"json"}).$type<string[]>()`
    else if (field.type === "json")
      column = `text("${snake(key)}", {mode:"json"}).$type<Record<string, unknown>>()`
    else column = `text("${snake(key)}")`
    if (field.required !== false) column += ".notNull()"
    if (field.unique) column += ".unique()"
    if (
      field.defaultValue !== undefined &&
      typeof field.defaultValue !== "function"
    )
      column += `.default(${JSON.stringify(field.defaultValue)})`
    if (field.references) {
      const r = field.references
      column += `.references(() => ${r.model}.${r.field}, {onDelete: "${r.onDelete ?? "cascade"}"})`
    }
    if (field.index)
      indexes.push(`index("${snake(name)}_${snake(key)}_idx").on(t.${key})`)
    fields.push(`${key}: ${column}`)
  }
  for (const [i, idx] of (table.indexes ?? []).entries())
    indexes.push(
      `${idx.unique ? "uniqueIndex" : "index"}("${snake(name)}_${i}_idx").on(${idx.fields.map((key) => `t.${key}`).join(",")})`
    )
  source += `export const ${name} = sqliteTable("${snake(name)}", {${fields.join(",\n")}}${indexes.length ? `, t => [${indexes.join(",\n")}]` : ""})\n\n`
}
writeFileSync(
  new URL("../packages/auth/src/oauth-schema.ts", import.meta.url),
  source
)
